export const engineeringSources = [{"id": "ga-ufms", "title": "Vetores e Geometria Analítica", "publisher": "Marcelo Henriques de Carvalho · UFMS / eduCAPES", "url": "https://educapes.capes.gov.br/handle/capes/600675", "accessedAt": "2026-09-28"}, {"id": "ee-unb", "title": "Noções Básicas de Engenharia Econômica", "publisher": "Ivan Camargo · FINATEC / UnB", "url": "https://repositorio.unb.br/handle/10482/16092", "accessedAt": "2026-09-28"}];
export const engineeringTopics:{id:string;subject:SubjectId;name:string;summary:string}[] = [{"id": "topic-226", "subject": "geometria-analitica", "name": "Distância entre pontos", "summary": "A distância no plano é √((x₂−x₁)²+(y₂−y₁)²). No espaço, some também (z₂−z₁)²."}, {"id": "topic-227", "subject": "geometria-analitica", "name": "Ponto médio", "summary": "Calcule a média das coordenadas correspondentes dos extremos para obter o ponto médio."}, {"id": "topic-228", "subject": "geometria-analitica", "name": "Operações com vetores", "summary": "Some e subtraia vetores coordenada a coordenada. Um escalar multiplica todas as componentes."}, {"id": "topic-229", "subject": "geometria-analitica", "name": "Produto escalar e ortogonalidade", "summary": "u·v é a soma dos produtos das componentes correspondentes. Vetores não nulos são ortogonais quando u·v=0."}, {"id": "topic-230", "subject": "geometria-analitica", "name": "Produto vetorial e áreas", "summary": "Em R³, u×v é perpendicular a u e a v. Sua norma é a área do paralelogramo gerado por eles."}, {"id": "topic-231", "subject": "geometria-analitica", "name": "Equações da reta", "summary": "Uma reta não vertical pode ser escrita como y=mx+b. O coeficiente m mede a variação de y por unidade de x."}, {"id": "topic-232", "subject": "geometria-analitica", "name": "Distância de ponto a reta", "summary": "Para ax+by+c=0, a distância de (x₀,y₀) é |ax₀+by₀+c|/√(a²+b²)."}, {"id": "topic-233", "subject": "geometria-analitica", "name": "Circunferências", "summary": "A equação (x−h)²+(y−k)²=r² representa uma circunferência de centro (h,k) e raio r."}, {"id": "topic-234", "subject": "geometria-analitica", "name": "Cônicas: elipse, hipérbole e parábola", "summary": "Na elipse x²/a²+y²/b²=1, com a>b>0, c²=a²−b². A hipérbole usa uma diferença de quadrados e a parábola pode ser escrita como y²=4px."}, {"id": "topic-235", "subject": "geometria-analitica", "name": "Planos e vetores normais", "summary": "No plano ax+by+cz=d, o vetor (a,b,c) é normal ao plano. Substitua as coordenadas para verificar a pertinência de um ponto."}, {"id": "topic-236", "subject": "engenharia-economica", "name": "Juros simples", "summary": "Em juros simples, J=Cin e M=C(1+in). Taxa i e prazo n devem usar a mesma unidade de tempo."}, {"id": "topic-237", "subject": "engenharia-economica", "name": "Juros compostos", "summary": "Em juros compostos, M=C(1+i)ⁿ. Os juros de cada período incorporam os juros acumulados anteriormente."}, {"id": "topic-238", "subject": "engenharia-economica", "name": "Taxas equivalentes e inflação", "summary": "Taxas efetivas equivalentes satisfazem 1+i_longo=(1+i_curto)ⁿ. A taxa real é (1+i_nominal)/(1+inflação)−1."}, {"id": "topic-239", "subject": "engenharia-economica", "name": "Séries uniformes", "summary": "Uma série postecipada paga ao fim de cada período. Seu valor presente é A[1−(1+i)^−n]/i, para i≠0."}, {"id": "topic-240", "subject": "engenharia-economica", "name": "Valor presente líquido — VPL", "summary": "VPL é a soma dos fluxos descontados à TMA, incluindo o investimento inicial negativo. Um VPL positivo indica ganho acima dessa taxa nas hipóteses adotadas."}, {"id": "topic-241", "subject": "engenharia-economica", "name": "Taxa interna de retorno — TIR", "summary": "TIR é uma taxa que zera o VPL. Fluxos não convencionais podem ter múltiplas TIR; comparações de projetos excludentes exigem cuidado."}, {"id": "topic-242", "subject": "engenharia-economica", "name": "Payback simples e descontado", "summary": "Payback mede o tempo de recuperação do investimento. O simples ignora o valor do dinheiro no tempo; o descontado considera a taxa escolhida."}, {"id": "topic-243", "subject": "engenharia-economica", "name": "Depreciação linear", "summary": "No modelo linear, a depreciação anual é (custo−valor residual)/vida útil. Depreciação contábil não é uma saída anual de caixa por si só."}, {"id": "topic-244", "subject": "engenharia-economica", "name": "Custos e ponto de equilíbrio", "summary": "Com preço unitário p, custo variável v e custo fixo F, o ponto de equilíbrio em unidades é F/(p−v), se p>v."}, {"id": "topic-245", "subject": "engenharia-economica", "name": "Custo anual uniforme equivalente — CAUE", "summary": "Transforme valores presentes em uma série anual equivalente pela taxa e horizonte definidos. Ao comparar alternativas com mesmo serviço, prefira o menor custo anual equivalente."}];
